function visuFrame(){
  if(VISU.frame) return VISU.frame;
  const f = document.createElement("iframe");
  f.className = "visu-frame"; f.title = "3D customer feedback heat map"; f.src = "visu/index.html?embed=1";
  document.body.appendChild(f); VISU.frame = f;
  window.addEventListener("message", e => {
    if(e.origin !== location.origin || e.source !== f.contentWindow) return;
    const d = e.data || {};
    if(d.type === "visu:ready"){ VISU.ready = true; visuSend(); }
    else if(d.type === "visu:select"){ VISU.sel = d.id ? d : null; if(VISU.onSel) VISU.onSel(VISU.sel); }
