}
// Study entry of a driver for the current model and market (BMW.study: items, ref, code, weak = satisfaction gap 0-100).
const studyOf = (id, market = state.market) => BMW.study[id]?.[state.model]?.[market] || null;
// No owner comments for China: score the parts by the China study of their linked drivers, ranked like the
// comment heat map (0 = biggest gap, 100 = smallest); parts without a study item stay neutral.
function studyOverride(){
  if(state.market !== "CN" || !sold("CN")) return null;
  const per = {};
  for(const id of Object.keys(PART)){ const st = studyOf(id); if(st) PART[id].forEach(p => (per[p] = per[p] || []).push(100 - st.weak)); }
  const avg = Object.fromEntries(Object.entries(per).map(([p, v]) => [p, v.reduce((a, b) => a + b, 0) / v.length]));
  const vals = [...new Set(Object.values(avg).map(v => v.toFixed(3)))].sort((a, b) => a - b);
  const scores = Object.fromEntries(Object.entries(avg).map(([p, v]) => [p, vals.length > 1 ? Math.round(100 * vals.indexOf(v.toFixed(3)) / (vals.length - 1)) : 50]));
  const code = Object.keys(PART).map(id => studyOf(id)?.code).find(Boolean) || M().code;
  return {scores, label:`${M().name} · China · customer study 2025 (${code}), ${Object.keys(scores).length} parts via the purchase drivers`,
    note:"No owner comments for China in the Dataset: parts coloured by the China customer study of their purchase drivers, parts without a study item stay neutral (50)"};
}
function visuSend(extra = {}){
  if(!VISU.ready) return;
  VISU.frame.contentWindow.postMessage({type:"visu:context", series:M().code, market:sold(state.market) ? state.market : "",
