  hits.splice(3);
  if(!o && !hits.length) return "";
  return `<div class="fc-opt"><span class="muted">Options today (${code} price list)</span>
    ${o ? `<small><b>${esc(o[0])}</b>${o[1] && o[1] !== "standard" ? " · " + esc(o[1]) : o[1] === "standard" ? " · standard" : ""}${o[2] ? " · " + eur(o[2]) : ""}</small>` : ""}
    ${hits.map(x => `<small>${esc(x.name)} · ${esc(x.availability)}${x.package && x.package !== "unclear" ? " · " + esc(x.package) : ""}${x.price_eur ? " · " + eur(x.price_eur) : ""}</small>`).join("")}</div>`;
}
function studyHtml(id){
  const st = id && studyOf(id); if(!st) return "";
  return `<div class="fc-opt"><span class="muted">Customer study ${esc(mkLabel())} (${esc(st.code)})</span>
    ${st.items.map(it => `<small>${esc(it[0])}: <b>${it[1]}</b> / ${st.scale} (overall ${st.ref})</small>`).join("")}
    <small>Satisfaction gap ${st.weak} / 100</small></div>`;
