  if(!d) return "";
  const x = d.detail, FT = {"Likes":"likes", "Defect":"defects", "Difficult to Use":"difficult to use", "Wants":"wants"};
  const counts = x ? Object.entries(x.counts).map(([k, v]) => `${fmt(v)} ${FT[k] || k}`).join(" · ") : "";
  const q = x && x.quotes && x.quotes[0];
  return `<div class="fc-part"><div><span class="muted">On the car</span> <b>${esc(d.name)}</b> <span class="heat">${d.score}/100</span></div>
    ${x ? `<small>${fmt(x.comments ?? x.n)} comments (${fmt(x.n)} classified mentions)${x.basis === "specific" ? "" : " (" + esc(x.basis) + " feedback)"} · ${counts} · ${x.positive_share}% positive</small>` : ""}
    ${q ? `<q>${esc(q.text.slice(0, 180))}${q.text.length > 180 ? "…" : ""}</q><small class="muted">${esc(q.type)} · ${esc(q.series)} · ${esc(q.country)}</small>` : ""}
    <small class="muted">${esc(d.data)}${d.fallback ? " · " + esc(d.fallback) : ""}</small>
